UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Build the ''Proof Generation'' loading state. This is a massive compute task, so create a multi-stage loading skeleton with dynamic progress text (e.g. ''Proving circuit...'', ''Generating witness...''). *(Resource: [Vercel v0 loading state examples](https://v0.dev/))*' WHERE day_number = 110;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Implement the success state: a beautiful dashboard view displaying the ML prediction, the ZK proof hash, and execution time stats. *(Resource: [Tremor React Components](https://tremor.so/))*' WHERE day_number = 111;
