UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Integrate the compiled Rust WASM **verifier only** (not the prover — proof generation stays on your Rust proving service, not in the browser) into the Next.js frontend. Configure Turbopack/Webpack to load `.wasm` files. *(Resource: [Next.js WebAssembly](https://nextjs.org/docs/app/api-reference/next-config-js/serverComponentsExternalPackages))*' WHERE day_number = 113;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Create a Web Worker to run WASM proof *verification* off the main thread so the UI never freezes. Proof *generation* is a network call to your Rust proving service, not worker work — keep the two paths architecturally separate. *(Resource: [MDN Web Workers](https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Using_web_workers))*' WHERE day_number = 114;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Implement the communication bridge between the React components (UI) and the Web Worker (WASM execution) using `postMessage`. *(Resource: [Comlink library for Workers](https://github.com/GoogleChromeLabs/comlink))*' WHERE day_number = 115;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Hook up the file upload component to send data to your Rust proving service (gRPC/REST) for proof *generation*, then verify the returned proof client-side via the WASM verifier in the Worker. Return the boolean result to the UI. *(Resource: [WASM-Bindgen Guide](https://rustwasm.github.io/docs/wasm-bindgen/))*' WHERE day_number = 116;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Add cryptographic flair. When the proof is verifying, render a matrix-like or cryptographic hash visualization using a Canvas element. *(Resource: [Codepen Canvas effects](https://codepen.io/))*' WHERE day_number = 117;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Implement error handling for both failure surfaces: the WASM verifier (catch a Rust panic, display a styled error toast) and the proving-service network call (timeout, 5xx, connection drop — these are now separate and more likely to fail than the verifier). *(Resource: [Sonner Toast component](https://sonner.emilkowal.ski/))*' WHERE day_number = 118;
UPDATE rust_challenge_days SET frontend_task = 'zkML UI: Build the UI for the reality your backend just stress-tested — a proving queue. Show real queue position / estimated wait when the proving service is under concurrent load, instead of a bare spinner that looks broken after 10 seconds.' WHERE day_number = 119;
